<?php
namespace App\\Http\\Controllers;use App\\Models\\Product;use Illuminate\\Http\\Request;class CartController extends Controller{public function index(){$cart=session('cart',[]);$products=Product::whereIn('id',array_keys($cart))->get()->keyBy('id');$currency=session('currency','USD');$total=0;foreach($cart as $id=>$line)if(isset($products[$id]))$total+=(float)$products[$id]->price($currency)*(int)$line['quantity'];return view('cart.index',compact('cart','products','currency','total'));}public function add(Request $r,Product $product){$d=$r->validate(['quantity'=>'nullable|integer|min:1|max:50']);abort_unless($product->is_active&&$product->stock>0,422,'Produit indisponible');$cart=session('cart',[]);$id=$product->id;$qty=($cart[$id]['quantity']??0)+($d['quantity']??1);if($qty>$product->stock)return back()->withErrors(['quantity'=>'Stock insuffisant.']);$cart[$id]=['quantity'=>$qty];session(['cart'=>$cart]);return back()->with('success','Produit ajouté au panier.');}public function update(Request $r,Product $product){$d=$r->validate(['quantity'=>'required|integer|min:1|max:50']);if($d['quantity']>$product->stock)return back()->withErrors(['quantity'=>'Stock insuffisant.']);$cart=session('cart',[]);if(isset($cart[$product->id])){$cart[$product->id]['quantity']=$d['quantity'];session(['cart'=>$cart]);}return back();}public function remove(Product $product){$cart=session('cart',[]);unset($cart[$product->id]);session(['cart'=>$cart]);return back();}public function currency(Request $r){$d=$r->validate(['currency'=>'required|in:USD,CDF']);session(['currency'=>$d['currency']]);return back();}}
